RAKIA.TEXTS.planetHouse.sun = RAKIA.TEXTS.planetHouse.sun || {};
RAKIA.TEXTS.planetHouse.sun[1] = T("שמש בבית הראשון שמה את הזהות במרכז הבמה. הכוח כאן הוא נוכחות ברורה ורצון להוביל, והאתגר הוא לשמוע גם אחרים כשהאור מופנה פנימה. למשל, בישיבת צוות מי שנושא את זה מדבר ראשון, מציע כיוון, וכולם כבר יודעים מה הוא חושב עוד לפני שמישהו אחר פתח את הפה. זה מזיז דברים, ולפעמים גם משאיר אנשים בלי מקום. מה שעוזר הוא לשאול לפני שמחליטים, ולתת לאחרים לומר דבר אחד קודם. האור נשאר, והוא מאיר גם את מי שיושב ליד.");
RAKIA.TEXTS.planetHouse.sun[2] = T("כשהשמש בבית השני, תחושת הערך נבנית ממה שנבנה ביד. יש כאן יציבות ונאמנות למה שחשוב, ולצד זה קושי לוותר על ההרגלים. למשל, בבית מבולגן מי שנושא את זה מסדר קודם את הפינה שלו, את המדף עם החפצים שנאספו בעבודה קשה, ורק אז מתפנה לשאר. הדברים האלה אינם סתם חפצים, הם סימן למה שנעשה. עוזר לזכור שהערך אינו תלוי רק במה שיש, וגם לשחרר מדי פעם דבר אחד ישן. מה שבאמת חשוב נשאר גם בלי המדף.");
RAKIA.TEXTS.planetHouse.sun[3] = T("שמש בבית השלישי מאירה את הדיבור, הלמידה והסביבה הקרובה. הסקרנות כאן פעילה ומהירה, והאתגר הוא להישאר בנושא אחד עד הסוף. למשל, בארוחת ערב מי שנושא את זה פותח שיחה על סרט, עובר לשכן החדש, ומשם לרעיון ששמע ברדיו, וכולם צוחקים ומנסים לעקוב. השיחה חיה, ורק בסוף מישהו שואל על מה בעצם דיברנו. עוזר לכתוב את מה שנלמד ולסגור נושא אחד לפני שפותחים את הבא. הסקרנות הזאת היא מתנה, וכשיש לה כיוון היא גם מגיעה לאנשהו.");
RAKIA.TEXTS.planetHouse.sun[4] = T("יש כאן שמש בבית הרביעי, והזהות צומחת מהבית ומהשורשים. הכוח הוא תחושת שייכות עמוקה, והאתגר הוא לצאת החוצה גם כשנוח בפנים. למשל, כשחברים מזמינים לטיול של יום שלם, מי שנושא את זה מעדיף להישאר, לבשל משהו מוכר ולשבת עם המשפחה, והעולם שבחוץ נשאר בחוץ. הבית נותן כוח, וגם עלול להפוך לקיר. עוזר לבנות בית שמאפשר גם ללכת, ולומר כן להזמנה אחת בחודש. הדלת נשארת פתוחה לשני הכיוונים.");
RAKIA.TEXTS.planetHouse.sun[5] = T("שמש בבית החמישי מבקשת ליצור, לשחק ולהיראות. יש כאן שמחה וביטוי עצמי חופשי, ולצד זה נטייה להיפגע כשאין קהל. למשל, מי שנושא את זה מספר סיפור מצחיק בארוחה, וכשאיש אינו צוחק החיוך נופל והשיחה נעשית שקטה. הצורך להיראות אינו חולשה, הוא הדלק של היצירה. מה שמאזן הוא ליצור גם בלי מחיאות כפיים, ולשאול אם הדבר משמח גם כשאין מי שרואה. השמחה שנשארת אחרי שהקהל הלך היא האמיתית.");
RAKIA.TEXTS.planetHouse.sun[6] = T("מי שנושא שמש בבית השישי מוצא את עצמו בעבודה היומיומית ובשגרה. הכוח הוא דיוק ומסירות, והאתגר הוא לשכוח את הגוף ואת המנוחה. למשל, ביום עבודה ארוך הוא נשאר לסדר את הטבלה עד שהכול נכון, מדלג על ארוחת הצהריים, ורק בערב מגלה שהגב תפוס מהישיבה. העשייה נותנת משמעות, והגוף משלם כשאין הפסקה. עוזר להכניס הפסקות ללוח, ולקום מהכיסא בכל שעה. שגרה טובה כוללת גם את מי שעושה אותה.");
RAKIA.TEXTS.planetHouse.sun[7] = T("שמש בבית השביעי מגלה את הזהות דרך שותפות. יש כאן כישרון לראות את הצד השני ולעבוד יחד, ולצד זה נטייה להישען יותר מדי על מה שאחרים חושבים. למשל, כשצריך לבחור סרט לערב, מי שנושא את זה שואל מה בן הזוג רוצה, מסכים מיד, ובסוף מגלה שלא בדק מה הוא עצמו היה רוצה לראות. הקשר נותן כוח, והקול העצמי לפעמים נעלם בתוכו. עוזר לזכור מה חשוב באמת בלי קשר לאחר, ולומר דעה לפני ששואלים. שותפות טובה צריכה שני קולות.");
RAKIA.TEXTS.planetHouse.sun[8] = T("כשהשמש בבית השמיני, החיים נמשכים אל העומק ואל השינוי. הכוח כאן הוא עוצמה ונכונות להיכנס למקומות שאחרים נמנעים מהם, והאתגר הוא לשלוט בכל דבר. למשל, כשחבר עובר תקופה קשה, מי שנושא את זה יושב איתו עד מאוחר ולא בורח מהשיחה הכבדה, ובאותו זמן רוצה גם לנהל לו את הפתרון. הנוכחות הזאת נדירה, והאחיזה החזקה מעייפת את שני הצדדים. עוזר להרפות מעט ולסמוך, ולהניח לאחר לבחור בעצמו. העומק נשאר גם כשהיד פתוחה.");
RAKIA.TEXTS.planetHouse.sun[9] = T("שמש בבית התשיעי מחפשת משמעות, מסע ואופק רחב. יש כאן אמונה ורצון ללמוד את העולם, ולצד זה קוצר רוח לפרטים הקטנים שבדרך. למשל, מי שנושא את זה מתכנן טיול גדול לארץ רחוקה, קורא על ההיסטוריה שלה בהתלהבות, ושוכח לבדוק אם הדרכון בתוקף. החזון מרים, והדרך אליו עשויה מצעדים קטנים ומשעממים. עוזר לחבר את החזון הגדול לצעד אחד היום, ולעשות את הצעד לפני שחולמים על הבא. האופק מחכה גם למי שהולך לאט.");
RAKIA.TEXTS.planetHouse.sun[10] = T("שמש בבית העשירי מכוונת את הזהות אל הדרך והתפקיד בעולם. הכוח הוא שאפתנות ואחריות, והאתגר הוא למדוד את הערך העצמי רק לפי הישגים. למשל, בארוחת שישי כששואלים מה שלומך, מי שנושא את זה עונה מה קורה בעבודה, ואם הימים היו שקטים הוא מרגיש שאין לו מה לספר. התפקיד נותן גאווה, והוא גם עלול לבלוע את כל השאר. עוזר לזכור שיש חיים גם מחוץ לתפקיד, ולספר גם על הטיול ועל הספר. מי שיושב ליד השולחן אוהב את האדם, לא את התואר.");
RAKIA.TEXTS.planetHouse.sun[11] = T("יש כאן שמש בבית האחד־עשר, וזהות שפורחת בתוך קבוצה. הכוח הוא חזון ורוח חברית, והאתגר הוא ללכת לאיבוד בתוך הרבים. למשל, בקבוצת חברים שמתכננת ערב, מי שנושא את זה מרים את כולם, מציע רעיון גדול, ובסוף הולך למקום שהרוב בחר גם כשלא ממש רצה. הקבוצה נותנת כוח, וקל להישען עליה במקום לעמוד לבד. עוזר לשמור על קול משלו גם בתוך הקבוצה, ולומר לפעמים לא לתוכנית של כולם. חבר טוב הוא גם מי שיש לו דעה.");
RAKIA.TEXTS.planetHouse.sun[12] = T("שמש בבית השנים־עשר מאירה עולם פנימי שקט. יש כאן רגישות, דמיון ויכולת להיות לבד בשלום, ולצד זה קושי לתפוס מקום גלוי. למשל, בשיחה קבוצתית מי שנושא את זה יושב בצד, שם לב לכל דבר, מבין מה כל אחד מרגיש, ולא אומר מילה. וכשמישהו שואל לדעתו, מתברר שהיה לו הרבה מה לומר. השקט הזה הוא כוח, והוא גם מסתיר את מי שמחזיק אותו. עוזר לתת לפנימיות ביטוי קטן בחוץ, אמירה אחת בכל שיחה. גם אור עדין נראה בחדר.");

RAKIA.TEXTS.planetHouse.moon = RAKIA.TEXTS.planetHouse.moon || {};
RAKIA.TEXTS.planetHouse.moon[1] = T("ירח בבית הראשון מביא את הרגש אל פני השטח. הכוח כאן הוא רגישות והבנה מיידית של מצב הרוח בחדר, והאתגר הוא שינויים מהירים במצב הרוח. למשל, מי שנושא את זה נכנס לחדר, מרגיש מיד שמישהו עצוב, ובתוך דקה גם הוא כבר לא במצב רוח, בלי לדעת למה. הפנים מספרות הכול, ומה שמרגישים בבוקר לא דומה למה שמרגישים בצהריים. עוזר לשים לב מה של הרגע ומה קבוע, ולחכות רגע לפני שמגיבים. רגש שרואים הוא גם רגש שאפשר לדבר עליו.");
RAKIA.TEXTS.planetHouse.moon[2] = T("כשהירח בבית השני, הביטחון הרגשי נשען על יציבות ועל דברים מוכרים. יש כאן נאמנות למה שיש, ולצד זה קושי לשחרר. למשל, בארון יש עדיין הסוודר הישן מלפני שנים, ומי שנושא את זה אינו מסוגל להיפרד ממנו, כי הוא מרגיש בו בבית. הדברים המוכרים מרגיעים, וכשמשהו זז מהמקום שלו הלב נלחץ. עוזר לזכור שהרגשה טובה אינה תלויה רק במה שביד, ולנסות דבר חדש אחד קטן. הביטחון האמיתי יושב בפנים, לא בארון.");
RAKIA.TEXTS.planetHouse.moon[3] = T("ירח בבית השלישי מרגיש דרך מילים, שיחה וקשר קרוב. הכוח הוא לב שיודע לדבר על רגשות, והאתגר הוא ראש שלא נרגע גם בלילה. למשל, אחרי שיחה עם אח או עם שכן, מי שנושא את זה שוכב במיטה ומשחזר כל מילה, מה נאמר ומה היה צריך לומר אחרת. השיחה נותנת חום, והמחשבה עליה לא נגמרת. עוזר לכתוב לפני שמדברים, ולכתוב גם אחרי כדי לפנות את הראש. מילים על נייר נרגעות מהר יותר ממילים בראש.");
RAKIA.TEXTS.planetHouse.moon[4] = T("ירח בבית הרביעי מרגיש בבית בתוך הבית. יש כאן זיכרון רגשי חזק, דאגה ותחושת שייכות, ולצד זה נטייה להיאחז בעבר ובמוכר. למשל, ריח של תבשיל מהילדות מחזיר את מי שנושא את זה בבת אחת למטבח של סבתא, וכל השאר נעצר לרגע. הזיכרון הזה מחמם, וגם מקשה לקבל שינוי בבית, אפילו רהיט שזז. עוזר להשאיר מקום גם למה שחדש, ולהכניס הביתה מנהג אחד שלא היה שם קודם. הבית גדל כשיש בו גם עתיד.");
RAKIA.TEXTS.planetHouse.moon[5] = T("מי שנושא ירח בבית החמישי מרגיש דרך יצירה ומשחק. הכוח כאן הוא חום, שמחה ולב פתוח, והאתגר הוא רגש שמחפש קהל ותשומת לב. למשל, הוא מבשל ארוחה יפה לחברים, מסדר את השולחן בקפידה, ואם איש לא אומר מילה על האוכל הערב מרגיש חסר. הנתינה הזאת שמחה ואמיתית, והיא מבקשת שיראו אותה. עוזר ליצור גם כשאיש אינו רואה, ולשים לב לשמחה שבעשייה עצמה. הלב שמשחק נשאר צעיר.");
RAKIA.TEXTS.planetHouse.moon[6] = T("ירח בבית השישי מוצא שקט בשגרה ובעשייה קטנה. הכוח הוא דאגה לפרטים ולאחרים, והאתגר הוא ביקורת עצמית ורגשות שמורגשים בגוף. למשל, ביום מתוח מי שנושא את זה מסדר את המטבח עד שהוא נוצץ, ורק כשהבטן מתכווצת הוא מבין שמשהו הציק לו כל היום. הסדר מרגיע באמת, והגוף אומר מה שהפה לא אמר. עוזר לנוח לפני שהגוף מבקש, ולשאול בערב מה הרגיש היום. שגרה רכה היא גם דרך לאהוב את עצמו.");
RAKIA.TEXTS.planetHouse.moon[7] = T("ירח בבית השביעי זקוק לקשר כדי להרגיש שלם. יש כאן יכולת להקשיב ולתת, ולצד זה נטייה לשים את הצורך של האחר לפני הצורך שלו. למשל, כשבן הזוג עייף, מי שנושא את זה מוותר על התוכנית שלו לערב בלי לחשוב פעמיים, ואחר כך מרגיש ריק ואינו יודע למה. ההקשבה הזאת היא מתנה גדולה, והיא זקוקה גם לכיוון השני. עוזר לשאול מה מרגיש נכון מבפנים, לפני ששואלים את האחר. קשר טוב מחזיק שני לבבות.");
RAKIA.TEXTS.planetHouse.moon[8] = T("ירח בבית השמיני מרגיש בעוצמה ובעומק. הכוח כאן הוא יכולת להכיל שינוי גדול ולהיות נוכח במקומות קשים, והאתגר הוא רגש שנשמר בסוד. למשל, כששואלים בארוחת ערב מה קרה היום, מי שנושא את זה עונה בקצרה שהכול בסדר, בזמן שבפנים סוער ים שלם. הוא יודע לשבת עם אחרים ברגעים הקשים שלהם, ואת שלו הוא מחביא. עוזר לשתף אדם אחד שסומכים עליו, גם בחצי אמירה. סוד שמספרים לאדם אחד נעשה קל יותר.");
RAKIA.TEXTS.planetHouse.moon[9] = T("ירח בבית התשיעי מרגיש בבית בדרך ובלמידה. יש כאן אופטימיות ורצון להרחיב את הלב, ולצד זה חוסר סבלנות לשגרה ולפרטים. למשל, מי שנושא את זה מרגיש הכי חי בטיול במקום זר, וכשחוזרים הביתה לסידורים ולכביסה הרוח נופלת אחרי יומיים. הלב רוצה אופק, והחיים מלאים בימים רגילים. עוזר למצוא משמעות גם ביום רגיל, ספר חדש או דרך אחרת לעבודה. המסע יכול להתחיל גם בפינת הרחוב.");
RAKIA.TEXTS.planetHouse.moon[10] = T("כשהירח בבית העשירי, הרגש מחפש הכרה ומקום בעולם. הכוח הוא אחריות ורגישות לצרכים של הציבור, והאתגר הוא להסתיר רגשות כדי להיראות חזק. למשל, בעבודה מי שנושא את זה מחזיק פנים שקטות גם ביום קשה, ורק בדרך הביתה, לבד במכונית, הדמעות מגיעות. האנשים סומכים עליו, והוא לא נותן להם לראות שגם הוא צריך. עוזר להרשות רכות גם בתוך התפקיד, ולומר לעמית אחד שהיום היה קשה. חוזק אמיתי יודע גם להתרכך.");
RAKIA.TEXTS.planetHouse.moon[11] = T("ירח בבית האחד־עשר מרגיש שייך בתוך קבוצה וחברים. יש כאן חום שמתחלק בין רבים ורצון לחלום יחד, ולצד זה קושי בקרבה אחת ועמוקה. למשל, מי שנושא את זה מרגיש נהדר בערב עם עשרה חברים, ונלחץ קצת כשחבר אחד מבקש לשבת רק שניהם ולדבר ברצינות. הקבוצה מחממת, והיא גם מקום נוח להתחבא בו. עוזר לתת לחבר אחד להתקרב באמת, ולומר כן לשיחה בשניים. הלב גדול מספיק גם לקשר אחד עמוק.");
RAKIA.TEXTS.planetHouse.moon[12] = T("ירח בבית השנים־עשר מרגיש הרבה ולא בכל פעם יודע לומר את זה. הכוח כאן הוא חמלה ודמיון, והאתגר הוא רגשות שנשארים בפנים עד שמתעייפים. למשל, מי שנושא את זה בוכה בסרט על אדם זר, ואת העצב שלו עצמו הוא נושא שבועות בלי לספר לאיש. הרגישות הזאת מרגישה את כולם, וקל לה לשכוח את עצמה. עוזר להקדיש זמן קבוע לשקט, הליכה או כתיבה, שבו הרגש מקבל מקום. מה שנאמר בשקט לעצמו כבר אינו לבד.");

RAKIA.TEXTS.planetHouse.mercury = RAKIA.TEXTS.planetHouse.mercury || {};
RAKIA.TEXTS.planetHouse.mercury[1] = T("מרקורי בבית הראשון חושב ומדבר מהר, והמחשבה היא חלק מהזהות. הכוח הוא סקרנות ותגובה חדה, והאתגר הוא לדבר לפני שמקשיבים. למשל, מישהו מתחיל לספר על היום שלו, ומי שנושא את זה כבר משלים לו את הסוף ומוסיף פתרון, עוד לפני שהסיפור נגמר. המהירות הזאת מרשימה, והיא גם משאירה את הצד השני עם חצי סיפור בפה. עוזר לספור עד שלוש לפני התשובה, ולשאול שאלה אחת לפני שעונים. ראש מהיר שגם מקשיב הוא ראש חכם באמת.");
RAKIA.TEXTS.planetHouse.mercury[2] = T("כשמרקורי בבית השני, המחשבה מעשית ומחוברת לערכים ולמשאבים. יש כאן היגיון יציב ותכנון טוב, ולצד זה קושי לשנות דעה. למשל, כשחבר מציע דרך חדשה לסדר את הבית, מי שנושא את זה עונה שהשיטה הישנה עובדת, ומסביר בסבלנות למה, בלי לנסות את החדשה אפילו פעם אחת. התכנון שלו אמין, ורעיון חדש מחכה הרבה בדלת. עוזר לשמוע רעיון חדש עד הסוף, ולנסות אותו יום אחד לפני שמחליטים. גם דעה יציבה יכולה לזוז צעד.");
RAKIA.TEXTS.planetHouse.mercury[3] = T("מרקורי בבית השלישי נמצא בבית שלו: דיבור, למידה וסביבה קרובה. הכוח כאן הוא זריזות מחשבה וכישרון להסביר, והאתגר הוא פיזור בין נושאים רבים. למשל, על השולחן של מי שנושא את זה פתוחים שלושה ספרים, במחשב חמישה חלונות, ובראש עוד שני רעיונות למחר. הוא מסביר כל דבר בקלות, ומסיים מעט. עוזר לבחור נושא אחד ולסיים אותו, ולסגור את שאר החלונות בינתיים. מה שנגמר נשאר, ומה שהתחיל ולא נגמר מתפזר.");
RAKIA.TEXTS.planetHouse.mercury[4] = T("מרקורי בבית הרביעי חושב על הבית, על המשפחה ועל השורשים. יש כאן זיכרון טוב ושיחה חמה, ולצד זה נטייה לחשוב במעגלים על העבר. למשל, בארוחת חג מי שנושא את זה זוכר מי אמר מה לפני עשר שנים, מספר את זה בחיוך, ובלילה ממשיך לחשוב על אמירה אחת ישנה שעדיין צורבת. הזיכרון מחבר את כולם, והוא גם לא מרפה. עוזר להוציא את המחשבות מהראש אל הנייר, ולכתוב את הסיפור הישן פעם אחת עד הסוף. מה שנכתב מפסיק להסתובב.");
RAKIA.TEXTS.planetHouse.mercury[5] = T("מי שנושא מרקורי בבית החמישי חושב דרך משחק ויצירה. הכוח הוא הומור, סיפור ורעיונות מלאי צבע, והאתגר הוא לקחת ביקורת על הרעיונות באופן אישי. למשל, הוא מציע בצוות רעיון צבעוני למצגת, מישהו אומר שזה קצת יותר מדי, והוא שותק לשאר הישיבה ומרגיש שנפסל הוא עצמו ולא הרעיון. הרעיונות שלו משמחים את החדר, ולכן קשה לו כשלא כולם מקבלים אותם. עוזר להפריד בין הרעיון לבין הערך העצמי, ולזכור שרעיון שנדחה אינו אדם שנדחה. המשחק ממשיך גם אחרי לא אחד.");
RAKIA.TEXTS.planetHouse.mercury[6] = T("מרקורי בבית השישי חושב בדיוק, בסדר ובפרטים. יש כאן כישרון לארגן ולשפר שגרה, ולצד זה ביקורת שאינה נחה, גם על עצמו. למשל, מי שנושא את זה שולח הודעה בעבודה, ואחרי שהיא נשלחה קורא אותה שוב ושוב ומוצא פסיק שלא במקום, ומתעצבן על עצמו חצי שעה. הסדר שלו עוזר לכולם, והביקורת אוכלת אותו מבפנים. עוזר לשאול אם הפרט הזה באמת משנה, ולתת לדבר אחד ביום להיות לא מושלם. גם שגרה מדויקת צריכה אוויר.");
RAKIA.TEXTS.planetHouse.mercury[7] = T("מרקורי בבית השביעי חושב טוב יותר בשיחה עם אחר. הכוח כאן הוא הקשבה, משא ומתן ויכולת לראות שני צדדים, והאתגר הוא קושי להחליט לבד. למשל, לפני שמזמינים במסעדה מי שנושא את זה שואל מה כולם לוקחים, שוקל, ומחליט אחרון, וגם אז לא בטוח. בעבודה בצוות הוא זה שמגשר בין הדעות, וקל לו יותר לשמוע מה אחרים חושבים מלומר מה הוא חושב. עוזר לכתוב את הדעה לפני שמתייעצים, ולבחור לפעמים בלי לשאול. שני צדדים זה יתרון, כשיש גם צד משלו.");
RAKIA.TEXTS.planetHouse.mercury[8] = T("מרקורי בבית השמיני חוקר את מה שמתחת לפני השטח. יש כאן חשיבה חדה שרואה מה לא נאמר, ולצד זה נטייה לחשוד ולשמור מידע. למשל, כשהודעה לא נענתה כמה שעות, מי שנושא את זה כבר בנה בראש סיפור שלם על מה שקרה ולמה, ואת מה שהוא עצמו יודע הוא מגלה רק במנות קטנות. הראייה הזאת חדה באמת, ולפעמים היא רואה גם מה שאין. עוזר לומר בקול את מה שכבר הובן, ולשאול במקום לנחש. שאלה פשוטה חוסכת סיפור שלם.");
RAKIA.TEXTS.planetHouse.mercury[9] = T("כשמרקורי בבית התשיעי, המחשבה מחפשת תמונה גדולה ומשמעות. הכוח הוא אהבת למידה ושפות, והאתגר הוא לדלג על הפרטים בדרך אל הרעיון. למשל, מי שנושא את זה קורא כותרת של מאמר, כבר יש לו תאוריה שלמה, והוא מספר אותה בהתלהבות בארוחת ערב עוד לפני שקרא את השורה השנייה. ההתלהבות הזאת סוחפת, והפרטים לפעמים אומרים משהו אחר. עוזר לבדוק דוגמה אחת לפני המסקנה, ולקרוא עד הסוף. רעיון גדול שנבדק הוא רעיון שאפשר לסמוך עליו.");
RAKIA.TEXTS.planetHouse.mercury[10] = T("מרקורי בבית העשירי חושב על הדרך ועל התפקיד בעולם. יש כאן דיבור מסודר ויכולת לתכנן לטווח ארוך, ולצד זה קושי לדבר על מה שאינו מועיל. למשל, בהפסקת קפה כשכולם צוחקים על סרטון, מי שנושא את זה מחכה שהשיחה תחזור למשהו רציני, ומרגיש שהזמן הולך לאיבוד. התכנון שלו מדויק, והשיחה הקלה נראית לו כמו בזבוז. עוזר להרשות גם שיחה סתם, ולזכור שקשר עם אנשים נבנה גם בהפסקות. דיבור מסודר יודע גם לצחוק.");
