RAKIA.TEXTS.planetHouse.venus[2] = T("ונוס בבית השני אוהבת נוחות, יופי ודברים טובים. יש כאן טעם טוב ונאמנות למה שקרוב ללב, ולצד זה נטייה להיאחז בנוחות. למשל, מי שנושא את זה מסדר את הסלון עם שמיכה רכה, אור חם וריח טוב, ואז קשה לו מאוד לקום מהספה כשחבר מתקשר ומציע לצאת. היופי שהוא יוצר סביבו מרגיע, והוא גם מחזיק אותו במקום. עוזר להעריך גם את מה שאינו נראה, ולצאת מהספה לפחות פעם בשבוע בלי סיבה. גם הדרך יכולה להיות יפה.");
RAKIA.TEXTS.planetHouse.venus[3] = T("כשונוס בבית השלישי, האהבה עוברת דרך מילים ושיחה. הכוח הוא דיבור נעים וקשר קל עם שכנים ואחים, והאתגר הוא להישאר על פני השטח. למשל, מי שנושא את זה מחליף מילה חמה עם כל מי שהוא פוגש בחדר המדרגות, וכשאח מנסה לדבר איתו על משהו שמציק לו הוא מחליף נושא למשהו קל. הקלות הזאת נעימה לכולם, והיא מונעת מהשיחה להגיע לעומק. עוזר לומר גם את מה שפחות נעים, ולהישאר בשיחה כשהיא נעשית רצינית. מילים יפות עם אמת בתוכן שוות יותר.");
RAKIA.TEXTS.planetHouse.venus[4] = T("ונוס בבית הרביעי אוהבת בית חם ויפה. יש כאן חום משפחתי ורצון ליצור מקום נעים, ולצד זה קושי לצאת מהמוכר והנוח. למשל, מי שנושא את זה מארח את כל המשפחה בשישי, כל פינה מסודרת ומריחה טוב, ואל ההזמנה לחתונה בעיר אחרת הוא אומר אולי, כי רחוק ולא מכיר שם אף אחד. הבית שהוא בונה הוא מתנה לכולם, והוא גם הופך לגבול. עוזר להזמין פנימה גם את מה שזר, שכן חדש או מאכל ממקום רחוק. חום אמיתי לא נגמר בדלת.");
RAKIA.TEXTS.planetHouse.venus[5] = T("ונוס בבית החמישי אוהבת ליצור, לשחק ולהתאהב. הכוח כאן הוא שמחה, רומנטיקה וכישרון אמנותי, והאתגר הוא לרצות שהכול יהיה חגיגה. למשל, מי שנושא את זה מתכנן ערב מושלם, פרחים ומוזיקה ותאורה, ואז יום שלישי רגיל עם כביסה וסידורים נראה לו אפור ומאכזב. השמחה שהוא מביא מדבקת, והציפייה לחגיגה קבועה מעייפת את מי שלידו. עוזר למצוא יופי גם ביום רגיל, כוס קפה בשמש או שיר בדרך לעבודה. האהבה חיה גם בימים שאין בהם פרחים.");
RAKIA.TEXTS.planetHouse.venus[6] = T("מי שנושא ונוס בבית השישי אוהב דרך עשייה ודאגה קטנה. הכוח הוא נאמנות ועזרה בפועל, והאתגר הוא לאהוב רק כשזה מועיל למישהו. למשל, הוא מביא לעמית בעבודה תה כשהוא עייף, מסדר לבן הזוג את הבגדים למחר, וכשמישהו מציע לעזור לו הוא אומר שאין צורך ומרגיש לא בנוח. הדאגה שלו נראית במעשים קטנים כל יום, והוא שוכח שגם הוא ראוי לה. עוזר לקבל עזרה ולא רק לתת, ולומר תודה במקום אין צורך. אהבה זורמת לשני הכיוונים.");
RAKIA.TEXTS.planetHouse.venus[7] = T("ונוס בבית השביעי נמצאת במקום הטבעי שלה, בשותפות. יש כאן כישרון לקשר, פשרה והרמוניה, ולצד זה קושי להיות לבד בלי שותף. למשל, כשבן הזוג נוסע לכמה ימים, מי שנושא את זה מוצא את עצמו מסתובב בדירה בלי לדעת מה לאכול ומה לראות, כי הכול נעשה בשניים. הוא יודע לגשר בין אנשים ולעשות שלום, ואת עצמו לבד הוא מכיר פחות. עוזר לטפח קשר טוב גם עם עצמו, ערב אחד בשבוע רק שלו. מי שטוב לו לבד מביא לקשר יותר.");
RAKIA.TEXTS.planetHouse.venus[8] = T("ונוס בבית השמיני אוהבת בעומק, בעוצמה ובלי חצאי דברים. הכוח כאן הוא קרבה אמיתית ונאמנות, והאתגר הוא קנאה ורצון להחזיק חזק מדי. למשל, כשבן הזוג יוצא לערב עם חברים, מי שנושא את זה בודק את הטלפון כל רבע שעה, ושואל אחר כך מי היה שם ומה נאמר. האהבה הזאת שלמה ואינה מוותרת, ולפעמים היא חונקת. עוזר לסמוך ולהניח לקשר לנשום, ולעשות באותו ערב משהו טוב לעצמו. קשר עמוק חזק מספיק כדי להישאר גם ממרחק.");
RAKIA.TEXTS.planetHouse.venus[9] = T("ונוס בבית התשיעי אוהבת את הרחוק, את הזר ואת הלמידה. יש כאן פתיחות ושמחה בגילוי, ולצד זה חוסר שקט כשהקשר נעשה יומיומי. למשל, מי שנושא את זה מתאהב בטיול, בשיחה בשפה שאינו מכיר, ואחרי חצי שנה של ארוחות ערב מול הטלוויזיה הוא מתחיל להרגיש שמשהו חסר. הפתיחות שלו מרחיבה את כל מי שלידו, והשגרה נראית לו כמו סוף ההרפתקה. עוזר למצוא הרפתקה גם קרוב לבית, מסעדה חדשה או קורס משותף. גם אהבה ותיקה יכולה לגלות ארץ חדשה.");
RAKIA.TEXTS.planetHouse.venus[10] = T("כשונוס בבית העשירי, הקשר והיופי מחוברים לדרך ולתפקיד. הכוח הוא חן בעבודה ויכולת לחבר אנשים, והאתגר הוא לבחור לפי מה שנראה טוב מבחוץ. למשל, מי שנושא את זה בוחר מקום עבודה בגלל השם היפה והמשרד המרשים, וגם קשר בגלל איך שהוא נראה בעיני אחרים, ורק אחר כך שואל אם טוב לו שם באמת. החן שלו פותח לו דלתות בעולם, והתמונה מבחוץ לפעמים מטעה. עוזר לשאול מה טוב באמת, ולא רק מה נראה טוב. מה שמחזיק לאורך זמן הוא מה שמרגיש נכון מבפנים.");
RAKIA.TEXTS.planetHouse.venus[11] = T("ונוס בבית האחד־עשר אוהבת חברים, קבוצה וחזון משותף. יש כאן חמימות רחבה וקלות בקשרים, ולצד זה קושי להתמסר לאדם אחד. למשל, בטלפון של מי שנושא את זה יש עשר קבוצות פעילות, וכל ערב יש עם מי לצאת, וכשמישהו אחד רוצה להיות בשבילו יותר מחבר הוא מרגיש שנסגרת עליו הדלת. החום שלו מגיע לרבים, ופחות נשאר לאחד. עוזר לתת לחברות אחת עומק אמיתי, ולפגוש אדם אחד בלי הקבוצה. חבר לכולם יכול להיות גם חבר לאחד.");
RAKIA.TEXTS.planetHouse.venus[12] = T("ונוס בבית השנים־עשר אוהבת בשקט ובחמלה. הכוח כאן הוא רכות ויכולת לאהוב בלי תנאי, והאתגר הוא לוותר על עצמו למען אחר. למשל, מי שנושא את זה מבטל תוכנית משלו כדי לעזור למישהו שבקושי מכיר, ואת מה שהוא עצמו רוצה הוא אומר בלחש, אם בכלל. האהבה הזאת נותנת בלי לספור, ומי שלא סופר עלול להישאר בלי כלום. עוזר לשמור גבול קטן גם באהבה, ולומר פעם אחת ביום מה הוא צריך. חמלה מתחילה גם בבית, אצל עצמו.");

