RAKIA.TEXTS.planetHouse.mars[2] = T("מאדים בבית השני נלחם על מה שחשוב ועל המשאבים. יש כאן התמדה ועבודה קשה, ולצד זה עקשנות וקושי לוותר. למשל, כשבבית מתווכחים אם להחליף את הספה הישנה, מי שנושא את זה מגן עליה כאילו מדובר בכבוד המשפחה, כי הוא עבד קשה כדי להביא אותה. הוא יודע להחזיק ולבנות לאורך זמן, וכשמישהו נוגע במה ששלו הוא נלחם גם כשלא צריך. עוזר לשאול אם המאבק הזה באמת שווה את המרץ, ולבחור על מה להילחם. כוח שנשמר למה שחשוב מספיק לכל השאר.");
RAKIA.TEXTS.planetHouse.mars[3] = T("כשמאדים בבית השלישי, המילים חדות ומהירות. הכוח הוא דיבור ישיר וחשיבה זריזה, והאתגר הוא ויכוח שמתלקח מהר מדי. למשל, בקבוצת ההודעות של המשפחה מישהו כותב דבר קטן, ומי שנושא את זה עונה בתוך שנייה תשובה חדה, ובתוך דקה כולם כבר בוויכוח שאיש לא רצה. המילים שלו ברורות ואין בהן בלבול, וחדות בלי הפסקה חותכת גם את מי שקרוב. עוזר להקשיב עד הסוף לפני שמשיבים, ולהמתין עם ההודעה כמה דקות. דיבור ישר יכול להיות גם רך.");
RAKIA.TEXTS.planetHouse.mars[4] = T("מאדים בבית הרביעי מביא מרץ אל הבית והמשפחה. יש כאן הגנה על הקרובים וכוח לבנות, ולצד זה מתח בבית שמתפרץ. למשל, מי שנושא את זה מרכיב לבד את כל הרהיטים החדשים ביום אחד, ובאותו ערב מתפוצץ על כלים שנשארו בכיור. הוא מגן על מי שבבית כמו חומה, ולפעמים החומה עצמה רועשת. עוזר להוציא את המרץ בעשייה ולא במריבה, בעבודה בגינה או בהליכה ארוכה לפני השיחה. בית בטוח הוא גם בית שקט.");
RAKIA.TEXTS.planetHouse.mars[5] = T("מאדים בבית החמישי פועל דרך יצירה, משחק ותחרות. הכוח כאן הוא תשוקה ושמחה בעשייה, והאתגר הוא רצון לנצח בכל משחק. למשל, במשחק קופסה עם הילדים או עם חברים, מי שנושא את זה משחק ברצינות גמורה, וכשהוא מפסיד הערב מתקלקל לו ולפעמים גם לאחרים. הלהט הזה הופך כל פעילות לחיה ומרגשת, וכשהוא רק על הניצחון הוא מוחק את הכיף. עוזר לשחק גם בלי לספור נקודות, ולשים לב מי צוחק סביב השולחן. המשחק עצמו הוא הפרס.");
RAKIA.TEXTS.planetHouse.mars[6] = T("מי שנושא מאדים בבית השישי עובד קשה ומדויק. הכוח הוא חריצות ואומץ לתקן, והאתגר הוא לחץ בגוף וכעס על עצמו על כל טעות. למשל, הוא מסיים משימה בעבודה לפני כולם, מגלה שגיאה קטנה, ובמקום להיות מרוצה מהעבודה הוא מתעצבן על עצמו והכתפיים נתפסות עד הערב. הוא זה שמתקן מה שאחרים מתעצלים לתקן, והוא לא מרפה גם מעצמו. עוזר לתת לגוף תנועה ומנוחה, ריצה או הליכה שמוציאה את הלחץ. גם מי שעובד קשה מותר לו לטעות.");
