RAKIA.TEXTS.planetHouse.jupiter[1] = T("יופיטר בבית הראשון מביא אופטימיות ונדיבות אל ההופעה. הכוח כאן הוא אמונה בעצמו וחיוך שפותח דלתות, והאתגר הוא הגזמה ולקיחת יותר מדי על עצמו. למשל, בישיבת הורים מי שנושא את זה מתנדב לארגן את הטיול, את המסיבה וגם את ספר המחזור, וכולם מוחאים כפיים, ובבית הוא מגלה שאין לו מתי לעשות את כל זה. הרוח הטובה שלו סוחפת חדר שלם, והחשבון עם הזמן מגיע אחר כך. עוזר לבדוק מה באמת אפשר להספיק, ולומר כן לדבר אחד בכל פעם. חיוך שיש מאחוריו זמן שווה יותר.");
RAKIA.TEXTS.planetHouse.jupiter[2] = T("יופיטר בבית השני מרחיב את תחושת הערך ואת המשאבים. יש כאן נדיבות ואמון שיש מספיק, ולצד זה נטייה לבזבז ולהגזים. למשל, מי שנושא את זה מזמין את כל החברים לארוחה, מכין פי שניים ממה שצריך, וכעבור כמה ימים חצי מהאוכל נזרק והמקרר עדיין מלא. הנדיבות שלו אמיתית וכולם נהנים ממנה, והיד הרחבה לא בכל פעם בודקת מה יש. עוזר למדוד מה יש לפני שמרחיבים, ולרשום רשימה לפני הבישול. שפע אמיתי הוא לדעת גם מתי די.");
RAKIA.TEXTS.planetHouse.jupiter[3] = T("כשיופיטר בבית השלישי, הדיבור והלמידה מתרחבים. הכוח הוא סקרנות רחבה ויכולת להסביר בפשטות, והאתגר הוא לדבר הרבה ולהקשיב מעט. למשל, בנסיעה ארוכה ברכב מי שנושא את זה מספר סיפור אחרי סיפור, מסביר איך העולם עובד, ובסוף הנסיעה מגלה שלא שאל את מי שלידו אפילו שאלה אחת. הוא הופך כל נושא למעניין, ובאותו זמן הוא ממלא את כל האוויר. עוזר לשאול שאלה אחת לפני כל סיפור, ולחכות לתשובה. מי שמסביר טוב יכול גם ללמוד טוב.");
RAKIA.TEXTS.planetHouse.jupiter[4] = T("יופיטר בבית הרביעי מביא שפע ואמונה אל הבית. יש כאן בית פתוח ותחושת ביטחון פנימית, ולצד זה נטייה להגזים בנוחות. למשל, בבית של מי שנושא את זה יש בכל שישי אורחים, השולחן עמוס והדלת פתוחה, ובאותו זמן הוא עצמו לא יצא מהשכונה כבר חודשים כי טוב לו בפנים. הבית הזה מחמם את כל מי שנכנס, והנוחות שבו מרדימה. עוזר לצאת החוצה ולהביא הביתה משהו חדש, טיול או אדם שלא הכירו קודם. בית פתוח נפתח לשני הכיוונים.");
RAKIA.TEXTS.planetHouse.jupiter[5] = T("יופיטר בבית החמישי מרחיב את היצירה ואת השמחה. הכוח כאן הוא נדיבות, הומור ואהבת חיים, והאתגר הוא לקחת סיכון גדול מדי במשחק. למשל, מי שנושא את זה מארגן מסיבת הפתעה לחבר עם חמישים אנשים, כשהחבר בעצם רצה ערב שקט עם שלושה. הוא מביא צחוק ואור לכל מקום, ולפעמים הגודל בולע את מה שרצו באמת. עוזר לשמוח גם בקטן, ולשאול קודם מה ישמח את האחר. חגיגה קטנה ומדויקת נזכרת יותר מגדולה.");
RAKIA.TEXTS.planetHouse.jupiter[6] = T("מי שנושא יופיטר בבית השישי מוצא משמעות בשגרה ובעבודה. הכוח הוא חריצות שמחה ורצון לעזור, והאתגר הוא לקחת יותר משימות ממה שהגוף יכול. למשל, בעבודה הוא אומר כן לכל בקשה, עוזר לכל עמית שנתקע, ובסוף היום מגלה שהמשימות שלו עצמו נשארו במקום והגוף גמור. הרוח הטובה שלו עושה את יום העבודה של כולם קל יותר, והלוח שלו מתמלא בלי שהוא שם לב. עוזר להשאיר מקום ריק בלוח, ולומר לא אחד ביום. גם מי שעוזר לכולם צריך הפסקת צהריים.");
RAKIA.TEXTS.planetHouse.jupiter[7] = T("יופיטר בבית השביעי מרחיב את השותפות. יש כאן נדיבות בקשר ואמון באחר, ולצד זה ציפייה שהאחר ימלא את הכול. למשל, מי שנושא את זה מצפה שבן הזוג יהיה גם החבר הכי טוב, גם השותף לטיולים וגם מי שמבין כל מחשבה, וכשהוא רק אדם עייף אחרי יום עבודה זה מרגיש כמו אכזבה. הוא נותן בקשר ביד רחבה, והציפייה הרחבה באותה מידה מכבידה על מי שמולו. עוזר לזכור שגם שותף טוב אינו כל העולם, ולתת לחברים ולתחביבים חלק. קשר נושם כשלא הכול נשען עליו.");
RAKIA.TEXTS.planetHouse.jupiter[8] = T("יופיטר בבית השמיני מאמין גם בתוך שינוי עמוק. הכוח כאן הוא יכולת לצמוח ממשבר ולשתף בנדיבות, והאתגר הוא לסמוך יותר מדי בלי לבדוק. למשל, מי שנושא את זה מוסר לשותף חדש את המפתחות, את הסיסמאות ואת כל התוכניות אחרי שיחה אחת טובה, כי הוא מרגיש שאפשר לסמוך. האמון הזה פותח קשרים עמוקים, ולפעמים הוא נמסר לפני שנבדק. עוזר לשאול שאלה לפני שנותנים הכול, ולתת בשלבים. אמון שנבנה לאט מחזיק חזק יותר.");
RAKIA.TEXTS.planetHouse.jupiter[9] = T("יופיטר בבית התשיעי נמצא בבית שלו, במסע ובמשמעות. הכוח הוא אמונה, למידה רחבה ואהבת האופק, והאתגר הוא ביטחון שהאמת שלו היא היחידה. למשל, בשיחה עם חבר שחושב אחרת, מי שנושא את זה מסביר ומסביר, בחיוך ובסבלנות, ובעצם לא שמע רגע אחד את מה שהחבר אמר. הוא רואה תמונה גדולה ומדבר עליה בהתלהבות, ובאותה תמונה לפעמים אין מקום לציור של מישהו אחר. עוזר להקשיב למי שחושב אחרת, ולשאול מה הוא רואה משם. אופק רחב כולל גם נוף שלא הכיר.");
RAKIA.TEXTS.planetHouse.jupiter[10] = T("כשיופיטר בבית העשירי, הדרך בעולם מתרחבת. הכוח הוא שאפתנות ואמון בדרך, והאתגר הוא לקחת תפקיד גדול מהמידה. למשל, מציעים למי שנושא את זה לנהל צוות חדש, והוא אומר כן באותו רגע, לפני שבדק אם יש לו זמן, כוח ורצון לזה. הביטחון שלו מרים אותו למקומות גבוהים, והמידה לפעמים גדולה ממה שנוח לו ללבוש. עוזר לבדוק מה באמת מתאים לפני שאומרים כן, ולשאול אנשים שמכירים. הדרך הנכונה גדולה בדיוק במידה.");
RAKIA.TEXTS.planetHouse.jupiter[11] = T("יופיטר בבית האחד־עשר מרחיב את מעגל החברים ואת החזון. יש כאן רוח טובה ואמון באנשים, ולצד זה פיזור בין רעיונות רבים. למשל, מי שנושא את זה רשום בשלוש קבוצות התנדבות, מציע בכל אחת רעיון גדול, ומגיע לפגישות של אף אחת מהן באופן קבוע. הוא מאמין באנשים ובמחר טוב יותר, והאמונה הזאת מתפזרת על יותר מדי מקומות. עוזר לבחור חזון אחד ולתת לו זמן, ולהיות באמת בקבוצה אחת. חבר אחד שמגיע שווה יותר מעשרה שהבטיחו.");
RAKIA.TEXTS.planetHouse.jupiter[12] = T("יופיטר בבית השנים־עשר מאמין בשקט, מבפנים. הכוח כאן הוא חמלה ותחושה שיש על מה להישען, והאתגר הוא לברוח לחלום במקום לפעול. למשל, מי שנושא את זה יושב על הספה ומדמיין את הספר שיכתוב, את הטיול הגדול, את הבית שיבנה, והערב נגמר בלי שכתב שורה. השקט הפנימי שלו מרגיע גם את מי שסביבו, והחלום נעים כל כך שקשה לצאת ממנו. עוזר לחבר את האמונה לצעד קטן, שורה אחת היום. חלום שיש לו צעד ראשון כבר אינו רק חלום.");

