RAKIA.TEXTS.planetHouse.saturn[2] = T("סטורן בבית השני בונה ערך ומשאבים לאט, בזהירות ובעבודה. יש כאן התמדה ויכולת לשמור, ולצד זה חשש מתמשך שאין מספיק. למשל, המזווה של מי שנושא את זה מלא, המדפים מסודרים, ובכל זאת לפני כל דבר חדש שנכנס הביתה הוא עוצר ושואל אם באמת צריך, גם כשמדובר בדבר קטן שישמח אותו. הזהירות הזאת בונה בסיס שאינו נופל, והתחושה שחסר לא עוזבת גם כשיש. עוזר לספור מה יש ולא רק מה חסר, ולהרשות לעצמו דבר קטן וטוב. מה שנבנה לאט נשאר.");
RAKIA.TEXTS.planetHouse.saturn[3] = T("כשסטורן בבית השלישי, הדיבור והלמידה דורשים מאמץ. הכוח הוא חשיבה יסודית ומילים שנשקלות, והאתגר הוא לשתוק מחשש לטעות. למשל, בשיעור או בישיבה מי שנושא את זה יודע את התשובה, מנסח אותה בראש שלוש פעמים, ועד שהיא מוכנה מישהו אחר כבר אמר אותה. כשהוא כן מדבר, כולם מקשיבים, כי כל מילה שלו נבדקה. עוזר לדבר גם כשלא הכול מושלם, ולומר את הגרסה הראשונה. מילה שנאמרת בזמן שווה יותר ממילה מושלמת שנשארה בפנים.");
RAKIA.TEXTS.planetHouse.saturn[4] = T("סטורן בבית הרביעי מביא אחריות אל הבית והשורשים. יש כאן יכולת לבנות בסיס יציב, ולצד זה קור וריחוק במשפחה. למשל, מי שנושא את זה דואג שהבית יעבוד, הסידורים נעשים והמקרר מלא, ובארוחת הערב הוא יושב שקט ואינו שואל איך היה היום. הוא הקיר שהבית נשען עליו, וקיר לא בכל פעם יודע לחבק. עוזר להראות חום גם בלי סיבה מיוחדת, שאלה אחת או יד על הכתף. בסיס יציב הוא גם בסיס חם.");
RAKIA.TEXTS.planetHouse.saturn[5] = T("סטורן בבית החמישי מבקש רצינות גם ביצירה ובמשחק. הכוח כאן הוא משמעת אמנותית ועבודה מסודרת, והאתגר הוא קושי לשחק סתם. למשל, מי שנושא את זה לומד לנגן ומתאמן כל יום בדיוק, אבל כשחברים מבקשים שינגן משהו סתם בערב הוא מסרב, כי זה עדיין לא מספיק טוב. ההתמדה שלו מביאה ליצירה אמיתית ועמוקה, והדרישה מעצמו מוציאה מזה את הכיף. עוזר לתת ליצירה להיות לא מושלמת, ולנגן שיר אחד גם עם טעויות. משחק בלי ציון הוא עדיין משחק.");
RAKIA.TEXTS.planetHouse.saturn[6] = T("מי שנושא סטורן בבית השישי לוקח את השגרה והגוף ברצינות. הכוח הוא סדר, נאמנות ועבודה יסודית, והאתגר הוא נוקשות ודרישה גבוהה מהגוף. למשל, הוא קם באותה שעה כל יום, מתאמן גם כשהגוף מבקש לנוח, ואם יום אחד הסדר משתבש הוא מרגיש שהכול התפרק. הסדר הזה מחזיק אותו ואת כל מי שעובד לידו, והנוקשות לא משאירה מקום ליום פחות טוב. עוזר להכניס גמישות קטנה ללוח, יום אחד בשבוע בלי תוכנית. גוף שמקבל מנוחה עובד טוב יותר.");
RAKIA.TEXTS.planetHouse.saturn[7] = T("סטורן בבית השביעי בונה שותפות לאט, באחריות ובלי קיצורי דרך. יש כאן נאמנות לאורך זמן, ולצד זה חשש מקרבה וקושי לתת אמון מהר. למשל, אחרי כמה פגישות טובות עם מישהו חדש, מי שנושא את זה עדיין עונה להודעות באיחור ושומר מרחק, לא כי אינו רוצה, אלא כי הוא בודק שזה אמיתי. כשהוא כבר בפנים, הוא נשאר לשנים. עוזר להתחיל בצעד קטן של פתיחות, אמירה אחת על מה שמרגיש. אמון שנבנה לאט הוא אמון ששווה לחכות לו.");
RAKIA.TEXTS.planetHouse.saturn[8] = T("סטורן בבית השמיני לומד לעמוד בתוך השינוי העמוק. הכוח כאן הוא עמידות וכוח לעבור תקופה קשה, והאתגר הוא לסגור את הלב ולא לשתף. למשל, כשמי שנושא את זה עובר תקופה קשה, הוא ממשיך ללכת לעבודה, לבשל ולתפקד, וכששואלים מה שלומו הוא אומר שבסדר, ואיש אינו יודע כמה כבד לו. הוא מסוגל לעמוד במה שאחרים נופלים ממנו, והדלת הסגורה משאירה אותו לבד בפנים. עוזר להרשות לאדם אחד לראות, ולומר לו חצי ממה שקורה. גם קיר חזק צריך מישהו שיישען עליו.");
RAKIA.TEXTS.planetHouse.saturn[9] = T("כשסטורן בבית התשיעי, האמונה והמסע נבנים בשלבים. הכוח הוא חוכמה שנרכשת בעבודה ורצינות בלמידה, והאתגר הוא ספק בכל דבר. למשל, מי שנושא את זה לומד לתואר ובודק כל מקור פעמיים, וכשחבר מספר בהתלהבות על רעיון חדש הוא שואל מיד מה ההוכחה, והחבר מאבד את החשק לספר. החוכמה שלו אמיתית ונבנתה בעמל, והספק לפעמים מכבה את הניצוץ אצל אחרים ואצלו. עוזר להשאיר מקום לתקווה, ולומר לפעמים מעניין במקום מה ההוכחה. גם מסע איטי מגיע רחוק.");
RAKIA.TEXTS.planetHouse.saturn[10] = T("סטורן בבית העשירי נמצא בבית שלו, בדרך ובתפקיד. הכוח הוא שאפתנות, סבלנות ואחריות, והאתגר הוא לחץ להצליח וחשש להיכשל. למשל, מי שנושא את זה עובד על מצגת עד שלוש בלילה, מציג אותה בבוקר וכולם מרוצים, והוא זוכר רק את השקופית שהיה אפשר לשפר. הוא בונה דרך ארוכה ויציבה, והלחץ מבפנים לא נותן לו לעצור ולהסתכל אחורה. עוזר לזכור שהדרך ארוכה ויש זמן, ולסמן לעצמו מה כבר הושג. מי שמטפס לאט מגיע, וגם רואה את הנוף.");
