RAKIA.TEXTS.planetHouse.neptune[4] = T("נפטון בבית הרביעי מביא געגוע ודמיון אל הבית. יש כאן חמלה למשפחה ותחושת בית פנימית, ולצד זה שורשים לא ברורים. למשל, מי שנושא את זה זוכר את בית הילדות כמקום קסום, מלא ריחות ומוזיקה, ואח שגדל באותו בית זוכר משהו אחר לגמרי, ואיש מהם אינו טועה. הוא מרגיש בבית כמעט בכל מקום שיש בו לב פתוח, ואת הבית עצמו הוא רואה דרך ערפל רך. עוזר לבנות בית מציאותי, לא רק חלום, עם קירות שאפשר לגעת בהם ומנהג אחד קבוע. גם בית שמדמיינים צריך רצפה.");
RAKIA.TEXTS.planetHouse.neptune[5] = T("נפטון בבית החמישי יוצר מתוך חלום והשראה. הכוח כאן הוא אמנות, מוזיקה ורומנטיקה, והאתגר הוא לראות באחר יותר ממה שיש. למשל, אחרי פגישה ראשונה מי שנושא את זה כבר רואה את החיים המשותפים, את הבית ואת המוזיקה שתתנגן שם, והאדם שמולו בקושי אמר שתי אמירות על עצמו. הוא יוצר יופי ממה שאחרים לא רואים, ולפעמים הוא מצייר את היופי על אדם שאינו שם. עוזר ליצור ולהסתכל גם במציאות, ולשאול מה האדם הזה אמר בפועל. השראה שנוגעת בקרקע יוצרת דברים שנשארים.");
RAKIA.TEXTS.planetHouse.neptune[6] = T("מי שנושא נפטון בבית השישי עובד מתוך חמלה ורצון לעזור. הכוח הוא רגישות לצרכים של אחרים, והאתגר הוא שגרה שמתפזרת וגוף שמרגיש הכול. למשל, בעבודה הוא שם לב ראשון שעמית עצוב ויושב איתו, ובינתיים המשימה שלו נדחית, וכשהוא חוזר הביתה הוא עייף מעייפות של אנשים אחרים. הרגישות הזאת היא מתנה למי שסביבו, והיא אינה יודעת לשמור על סדר היום של מי שנושא אותה. עוזר לסדר יום פשוט ועדין, שעה קבועה לאכול ושעה קבועה לסיים. גם מי שמרגיש את כולם צריך גבול לשעות.");
RAKIA.TEXTS.planetHouse.neptune[7] = T("נפטון בבית השביעי מחפש שותפות אידיאלית, כמו בחלום. יש כאן אהבה נדיבה וחמלה, ולצד זה קושי לראות את האחר כפי שהוא באמת. למשל, מי שנושא את זה מסביר לחברים למה בן הזוג שוב איחר ושוב שכח, כי הוא רואה בו את מי שהוא יכול להיות, ולא את מי שעומד מולו עכשיו. הוא אוהב בלי חשבון, וזה יפה, וכשהתמונה שבראש רחוקה מהאדם שבבית, שניהם נפגעים. עוזר לשאול מה יש כאן בפועל, ולכתוב שלושה דברים שהאחר עושה באמת. אהבה שרואה את האדם עצמו מחזיקה יותר.");
RAKIA.TEXTS.planetHouse.neptune[8] = T("נפטון בבית השמיני מרגיש את העומק בלי מילים. הכוח כאן הוא אינטואיציה ויכולת להתמסר, והאתגר הוא לאבד את עצמו בתוך אחר. למשל, כשחבר קרוב עובר תקופה קשה, מי שנושא את זה מרגיש את הכובד שלו כאילו הוא שלו, לא ישן בלילה, ואחרי שבוע כבר אינו יודע מה מהעצב שייך לו ומה לחבר. הוא יודע להיות עם אנשים במקומות שאיש אינו מגיע אליהם, ובדרך הוא שוכח לחזור. עוזר לשמור גבול ברור ופשוט, לומר עד כאן זה שלו ומכאן זה שלי. מי ששומר על עצמו יכול להישאר לצד האחר לאורך זמן.");
RAKIA.TEXTS.planetHouse.neptune[9] = T("כשנפטון בבית התשיעי, האמונה רחבה ומלאת השראה. הכוח הוא רוחניות וחמלה לכל העולם, והאתגר הוא ללכת אחרי חלום בלי מפה. למשל, מי שנושא את זה שומע הרצאה על מקום רחוק ובאותו ערב כבר מחפש כרטיס, בלי לבדוק איפה ישן ואיך מסתדרים שם, כי הלב כבר שם. האמונה שלו רואה את הטוב בכל דרך ובכל אדם, וכשאין מפה גם דרך יפה מובילה לפעמים לשום מקום. עוזר לבדוק כל דרך בצעד אחד, ולשאול מישהו שכבר היה שם. חלום עם מפה מגיע רחוק יותר.");
RAKIA.TEXTS.planetHouse.neptune[10] = T("נפטון בבית העשירי מביא חלום אל הדרך בעולם. יש כאן תפקיד שנוגע לאנשים ולאמנות, ולצד זה קושי להגדיר מה בדיוק רוצים. למשל, כששואלים את מי שנושא את זה מה הוא רוצה לעשות בחיים, הוא עונה שמשהו שעוזר לאנשים ויש בו יופי, וכשמבקשים דוגמה אחת מדויקת הוא שותק. הכיוון שלו נכון ועמוק, והתמונה בראשו רחבה כל כך שקשה לבחור ממנה צעד. עוזר לכתוב את המטרה במילים פשוטות, מה עושים ביום שלישי בבוקר. חלום שיש לו שם הופך לדרך.");
RAKIA.TEXTS.planetHouse.neptune[11] = T("נפטון בבית האחד־עשר חולם יחד עם חברים על עולם טוב יותר. הכוח כאן הוא חזון וחמלה, והאתגר הוא לסמוך על כל מי שמדבר יפה. למשל, מי שנושא את זה פוגש מישהו חדש שמדבר על שינוי גדול ועל עזרה לכולם, ומצטרף לתוכנית שלו באותו ערב, ואחרי חודש מגלה שהמילים היו יפות והמעשים לא הגיעו. הוא מאמין בטוב שבאנשים, וזה מה שמחזיק קבוצות יחד, ומילים יפות אינן עדות למעשים. עוזר לבדוק מעשים ולא רק מילים, ולהסתכל מה האדם עשה עד עכשיו. חלום משותף צריך גם ידיים.");
