RAKIA.TEXTS.planetHouse.pluto[8] = T("פלוטו בבית השמיני נמצא בבית שלו, בשינוי העמוק ובשיתוף. הכוח כאן הוא יכולת להתחדש שוב ושוב, והאתגר הוא לאחוז בסוד ובשליטה. למשל, מי שנושא את זה עובר תקופה שהופכת לו את החיים, יוצא ממנה אדם אחר, וכשחבר ותיק שואל מה עבר עליו הוא עונה שלא הרבה ומחליף נושא. הוא נולד מחדש בכל פעם שהחיים דורשים, וכל לידה כזאת הוא עובר לבד ובסוד. עוזר לסמוך על אדם אחד, ולספר לו את הסיפור השלם פעם אחת. סוד שמשתפים בו אדם אחד עדיין נשאר סוד.");
RAKIA.TEXTS.planetHouse.pluto[9] = T("כשפלוטו בבית התשיעי, האמונה חזקה ומשנה את מי שנושא אותה. הכוח הוא חיפוש אמת עמוק, והאתגר הוא לדרוש שכולם יאמינו באותו דבר. למשל, מי שנושא את זה קורא ספר שהפך לו את התמונה, ובחודש שאחרי כל שיחה עם חברים נגמרת בניסיון לשכנע אותם, ומי שלא משתכנע מרגיש שנעשה פחות חבר. האמת שהוא מחפש אינה שטחית, והוא הולך אחריה עד הסוף, והדרישה שכולם ילכו איתו משאירה אותו לבד. עוזר להשאיר מקום פתוח לדעה אחרת, ולשאול מה החבר מאמין ולמה. אמת עמוקה אינה זקוקה לרוב.");
RAKIA.TEXTS.planetHouse.pluto[10] = T("פלוטו בבית העשירי מביא עוצמה אל הדרך והתפקיד בעולם. יש כאן שאפתנות ויכולת להשפיע, והאתגר הוא מאבק על כוח ומעמד. למשל, בעבודה מי שנושא את זה מקבל תפקיד חדש, ובתוך חודש כבר משנה את כל הסדר במחלקה, וכל מי שמתנגד הופך בעיניו ליריב במקום לעמית. הוא מסוגל לשנות מקום שלם מהיסוד, ובמאבק על כל שטח הוא מאבד את מי שהיה יכול ללכת איתו. עוזר לשאול לשם מה נועד הכוח הזה, ומה הוא בונה ולא רק על מה הוא שולט. השפעה אמיתית נשארת גם אחרי שהתפקיד נגמר.");
RAKIA.TEXTS.planetHouse.pluto[11] = T("פלוטו בבית האחד־עשר משנה את החברים ואת החזון מהיסוד. הכוח כאן הוא השפעה על קבוצה וחזון אמיתי, והאתגר הוא לנסות לשלוט בקבוצה. למשל, בקבוצת חברים שמתכננת מסע משותף, מי שנושא את זה בונה את כל התוכנית, ומי שרוצה לשנות פרט אחד מרגיש שהוא הולך נגד כולם, כי הוא הפך את התוכנית לשלו. הוא זה שמחזיק את הקבוצה כשהיא מתפרקת, והיד שמחזיקה גם לוחצת. עוזר לתת לאחרים להוביל לפעמים, ולהיות בטיול אחד רק משתתף. קבוצה חיה כשיש בה יותר מקול אחד.");
RAKIA.TEXTS.planetHouse.pluto[12] = T("פלוטו בבית השנים־עשר עובד בעומק ובשקט. יש כאן כוח פנימי ויכולת להתחדש מבפנים, ולצד זה רגשות עצומים שנשמרים בסוד. למשל, מי שנושא את זה מוצא את עצמו בוכה במקלחת אחרי יום רגיל לגמרי, ואינו יודע על מה, ואז מתלבש ויוצא לחדר בפנים רגילות. הכוח שלו עובד מתחת לפני השטח, כמו שורש, והרגש הגדול שאיש אינו רואה מבקש מקום. עוזר לתת לעומק מקום בטוח לצאת, כתיבה או שיחה קבועה עם אדם אחד שיודע להקשיב. מה שיוצא בשקט אל האור מפסיק להכביד.");
